>>> +
>>> +   # f2fs_io dev_alias release /mnt/f2fs/vdc.file
>>> +   # df -h
>>> +   /dev/vdb                            64G  753M   64G   2% /mnt/f2fs
>>> +
>>> +   # f2fs_io dev_alias reserve /mnt/f2fs/vdc.file
