 		drm_atomic_get_old_crtc_state(state, drm_crtc);
 	struct drm_device *drm_dev = drm_crtc->dev;
 	unsigned long flags;
+	int idx;
+
+	if (!drm_dev_enter(drm_dev, &idx)) {
+		logicvc_crtc_drop_any_event(drm_dev, drm_crtc);
+		return;
