+++ b/drivers/firmware/stratix10-svc.c
@@ -62,6 +62,9 @@
 #define SVC_SDM_DMA_ADDR_BITS			29
 #define SVC_SDM_DMA_ADDR_OFFSET			0x80000000UL
 
+/* Per-compatible feature flags stored in of_device_id.data */
+#define SVC_FLAG_USE_DMA_MEM			BIT(0)
